actions.script:
def gid = ec.web.session.getAttribute("googleIdentity")
subdomain = subdomain?.trim()?.toLowerCase()
def gstinClean = gstin?.trim()?.toUpperCase()
if (gstinClean && gstinClean.length() != 15) { ec.message.addError("GSTIN must be exactly 15 characters, or leave it blank."); return }
// Identity: from Google if present, else from the form
// Name comes from the (always-visible, Google-prefilled) form field, falling back to the
// Google identity — so a Google user whose account returned no name can still type one.
def fName = (adminFirstName?.trim()) ?: gid?.firstName
def lName = (adminLastName?.trim()) ?: gid?.lastName
def email = (gid?.email ?: adminEmail)?.trim()?.toLowerCase()
def gsub = gid?.googleSub
def pwd = gid ? null : adminPassword   // Google = passwordless; email signup keeps its password
context.needsVerification = false
// ZE-ONB-002: email/password signups must supply a valid email FORMAT (Google emails are pre-validated).
if (!gid && (!email || !(email ==~ /[^@\s]+@[^@\s]+\.[^@\s]+/))) { ec.message.addError("Please enter a valid email address."); return }
// ZE-AUTH-013: names are required by provision#Tenant; show a clear message rather than the raw
// "adminFirstName is required" (and instead of the old silent dead-end when Google returned no name).
if (!fName?.trim() || !lName?.trim()) { ec.message.addError("Please enter your first and last name."); return }
boolean alreadyDisabled = ec.artifactExecution.disableAuthz()
try {
    def result = ec.service.sync().name("zenith.saas.SaasServices.provision#Tenant")
        .parameters([tenantName:tenantName, subdomain:subdomain, countryGeoId:countryGeoId,
            industryEnumId:industryEnumId, adminFirstName:fName, adminLastName:lName,
            adminEmail:email, adminPhone:adminPhone, adminPassword:pwd, planId:planId,
            gstin:gstinClean, googleSub:gsub])
        .disableAuthz().requireNewTransaction(true).call()
    if (ec.message.hasError()) return
    context.putAll(result)
    if (gid) {
        // Google already verified the email -> mark verified and log in immediately.
        ec.entity.makeValue("moqui.security.UserPreference")
            .setAll([userId:result.userId, preferenceKey:"EMAIL_VERIFIED", preferenceValue:"Y"]).createOrUpdate()
        ec.user.internalLoginUser(email)
        ec.web.session.removeAttribute("googleIdentity")
    } else {
        // ZE-ONB-002 hard gate: DO NOT log in. Send a verification link; login stays blocked until verified.
        ec.service.sync().name("zenith.saas.SaasServices.send#SignupVerification")
            .parameters([email:email, firstName:fName]).disableAuthz().call()
        ec.web.session.setAttribute("pendingVerifyEmail", email)
        context.needsVerification = true
    }
} finally { if (!alreadyDisabled) ec.artifactExecution.enableAuthz() }

boolean alreadyDisabled = ec.artifactExecution.disableAuthz()
try {
    planList = ec.entity.find("zenith.erp.saas.SaasPlan").condition("isActive","Y").orderBy("sortOrder").list()
    countryList = ec.entity.find("zenith.erp.base.CountryConfiguration").orderBy("countryName").list()
    industryList = ec.entity.find("moqui.basic.Enumeration").condition("enumTypeId","TenantIndustry").orderBy("sequenceNum").list()
} finally { if (!alreadyDisabled) ec.artifactExecution.enableAuthz() }
context.googleIdentity = ec.web.session.getAttribute("googleIdentity")
// ZE-AUTH-013: pre-fill the (now always-visible) name fields from Google. Google does not always
// return given_name/family_name; hiding the fields then left such users unable to complete
// onboarding (provision failed "adminFirstName required" with no way to supply it). Showing them
// pre-filled lets every Google user finish and correct a wrong name. Keep any error-repopulated value.
if (context.googleIdentity) {
    if (!context.adminFirstName) context.adminFirstName = context.googleIdentity.firstName
    if (!context.adminLastName) context.adminLastName = context.googleIdentity.lastName
}
